import { describe, it, expect, vi, beforeEach } from 'vitest';
import AdminPage from './page';
import * as auth from '../lib/auth';
import * as navigation from 'next/navigation';

// Mock the modules
vi.mock('../lib/auth', () => ({
  verifyAdmin: vi.fn(),
}));

vi.mock('next/navigation', () => ({
  forbidden: vi.fn(),
}));

describe('AdminPage', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('calls forbidden() if user is not admin', async () => {
    vi.mocked(auth.verifyAdmin).mockResolvedValue({ isAdmin: false, session: null });

    // We expect AdminPage to potentially throw or just return nothing/promise depending on implementation of forbidden
    // But since forbidden() usually throws in Next.js, let's just see if it's called.
    try {
      await AdminPage();
    } catch (e) {
      // Ignore errors from forbidden() if it throws
    }

    expect(navigation.forbidden).toHaveBeenCalled();
  });

  it('does not call forbidden() if user is admin', async () => {
    vi.mocked(auth.verifyAdmin).mockResolvedValue({ 
      isAdmin: true, 
      session: { role: 'admin', userId: '1', name: 'Admin' } 
    });

    await AdminPage();

    expect(navigation.forbidden).not.toHaveBeenCalled();
  });
});
